#include <iostream>
using namespace std;

class Pile {
    private:
        int* donnees;
        int sommet;
        int capacite;
    public:
        Pile(int cap) : sommet(0), capacite(cap) {
            donnees = new int[capacite];
        }
        ~Pile() {
            delete[] donnees;
        }
        void empiler(int v) { donnees[sommet++] = v; }
        int depiler() { return donnees[--sommet]; }
        int taille() const { return sommet; }
};

int main() {
    int n;
    cin >> n;
    Pile p(n);
    for (int i = 0; i < n; i++) {
        int v;
        cin >> v;
        p.empiler(v);
    }
    cout << "taille = " << p.taille() << endl;
    while (p.taille() > 0) {
        cout << p.depiler() << " ";
    }
    cout << endl;
    return 0;
}

