#include <iostream>
using namespace std;

class Vecteur2D {
    private:
        int x, y;
    public:
        Vecteur2D(int x = 0, int y = 0) : x(x), y(y) {}
        Vecteur2D operator+(const Vecteur2D& autre) const {
            return Vecteur2D(x + autre.x, y + autre.y);
        }
        friend ostream& operator<<(ostream& os, const Vecteur2D& v) {
            os << "(" << v.x << ", " << v.y << ")";
            return os;
        }
};

int main() {
    Vecteur2D a(2, 3);
    Vecteur2D b(5, 1);
    Vecteur2D c = a + b;
    cout << a << " + " << b << " = " << c << endl;
    return 0;
}

