using namespace std;

class Argent {
    private:
        int centimes;
    public:
        Argent(int c = 0) : centimes(c) {}
        Argent operator+(const Argent& autre) const {
            return Argent(centimes + autre.centimes);
        }
        bool operator==(const Argent& autre) const {
            return centimes == autre.centimes;
        }
        friend ostream& operator<<(ostream& os, const Argent& a) {
            os << a.centimes;
            return os;
        }
};

int main() {
    int a, b;
    cin >> a >> b;
